# Q2: add the outflow separation / PV / wing flux / mass results (s74a, s75a-d) to /output/report.json. Re-runnable: starts from out/report_before_q2.json (first run saves it).
import json,shutil,os
R='/output/report.json'; B='/workspace/out/report_before_q2.json'
if not os.path.exists(B): shutil.copy(R,B)
r=json.load(open(B)); res=r['results']
A=lambda n,v:{'name':n,'value':v}
com=[A('distance','D=40 Mpc, 1"=194 pc; z from VSYS=2780 km/s radio-LSRK (s3b)'),
 A('data','Xb4d (0.94x0.74") and Xb4b (0.25") pbcor cubes HCN 3-2 spw27 / HCO+ 3-2 spw25, convolved (flux rescaled) to circular 1.05" (Xb4d, Xb4b) or 0.5" (PV only); native-beam peak-pixel spectra also given'),
 A('baseline','per-pixel median of -900<v-VSYS<-450 km/s (radio velocity)'),
 A('windows','blue -405..-150, red 150..405 and red-candidate 180..320 km/s about VSYS; core -205..+95'),
 A('noise','per-channel rms from line-free channels (units of the spectrum: Jy/beam for peak pixels, beam-averaged Jy for apertures); flux errors from 10-80 random line-free apertures (bright emission masked) or 15-30 injected-model refits in noise cut-outs'),
 A('clean mask','the wing emission lies OUTSIDE the Xb4d clean mask (0-4% of the signal inside), so Xb4d wing fluxes are residual-dominated (dirty-beam units): treat as lower limits (true/measured = clean-beam/dirty-beam area >~1; not measurable here)')]
def add(q,t,v,u,un,conf,ev,extra=()):
    res.append(dict(quantity=q,target=t,value=v,uncertainty=u,unit=un,assumptions=com+list(extra),confidence=conf,evidence='Q2: '+ev))
add('Is the dense-gas outflow separable from the nuclei and disk? Position-velocity structure along the S-outflow axis (PA 185 deg through S, the line also passes N and the Bridge) in HCN and HCO+ 3-2',
 'cut PA=185 deg, 1" wide (Xb4d@1.05") / 0.5" wide (Xb4b@0.5"), from 7" S to 7" N of the S nucleus',
 'YES for one lobe. In both lines and both arrays a blueshifted tail leaves the S nucleus and extends to about 3.5" (680 pc) S (HCN wing/total flux 0.14 at S, 0.57-0.59 at 2.0-2.5" S; blue-wing first-moment velocity -170 km/s at S, -240 km/s at 2" S, -220..-228 at 3-3.25" S, HCN; -146, -200, -192 for HCO+; PV maps in out/q2/s75a_pv.png). The disk/bridge/N gas along the same cut is narrow (FWHM 70-90 km/s) and sits at -10..+50 km/s, and the S and N nuclear profiles are double peaked (components near -60 and +50 km/s, FWHM ~90), i.e. the lobe velocities (-200..-350) are 4-6x the nuclear rotation amplitude. Lobe peak position (Xb4d@1.05", 2D Gaussian): HCN 0.10+-0.04" W, 1.88+-0.11" S of the S nucleus (PA 183+-1 deg), HCO+ 0.31+-0.12" W, 1.79+-0.45" S; deconvolved length ~2.0" (400 pc) along the axis, unresolved across (FWHM 2.3x1.0" convolved with the 1.05" beam). A 1.05" beam resolves it from S (1.8 beams). Red side: no blue/red counterpart at the same offset (red window at the lobe -0.1+-0.1 sigma); the only red feature is at +3.4" N (see its own entry).',
 'peak position +-0.1-0.45"; wing velocities +-10-20 km/s','arcsec, km/s','medium','s74a_wing_geometry.py -> out/q2/s74a.txt, s74a_maps.png; s75a_pv_spectra.py -> out/q2/s75a_pv.png, s75a.txt; s75b_wing_fits.py -> out/q2/s75b.txt (FIT, KIN lines)')
add('Spectral decomposition of the S blue lobe (1.88" S of S) and of the nuclei',
 'S blue lobe aperture r=1" (Xb4d@1.05"), native peak pixel; nuclei S and N',
 'LOBE (2 Gaussians, narrow + broad; Xb4d@1.05" aperture): HCN broad component centre -178+-10 km/s, FWHM 334 km/s, narrow +34 km/s FWHM 60 (dchi2=118 for 3 extra parameters); HCO+ broad -89+-8, FWHM 211, narrow +36 FWHM 63 (dchi2=328). Native Xb4d peak pixel: HCN broad -252+-20 FWHM 293 (dchi2=57); HCO+ broad -372+-27 FWHM 229, 0.7 mJy/beam (dchi2=32, marginal). Xb4b@0.5" aperture: HCN broad -108+-12 FWHM 235; HCO+ -98 vs narrow +41 (dchi2 53, 79). Peak amplitudes 2-5 mJy against 0.6-1.0 mJy/channel rms (Xb4d@1.05" aperture rms 0.86 HCN, 0.98 HCO+). Blue edge of contiguous emission >2 sigma (22 km/s bins, r=1" aperture): -349 km/s (HCN), -268 km/s (HCO+, -202 at 3 sigma): the projected maximum velocity is ~-350 km/s (noise-limited; the cubes extend to -1000 km/s). HCN centroid is more blue than HCO+ by ~90+-13 km/s (Gaussian model dependent; HCN/HCO+ is highest at the blue edge, consistent with team-a/our outer-window result). NUCLEI: both S and N have double-peaked profiles (2 narrow components at -62/+52 (S) and -58/+38 km/s (N), FWHM 70-94, chi2 ~740/323 vs 2 narrow + 1 broad 518/320 at S Xb4d); a 2-narrow+1-broad decomposition gives a broad (FWHM 230-305 km/s, centred -45..+6, i.e. NOT shifted) component at S of 29+-10% (HCN) and 14+-7% (HCO+) of the fitted line flux at the Xb4b native peak, and 17+-7% (HCN) and 7+-4% (HCO+) at N. This component is shape-model dependent (non-Gaussian double profiles, absorption) and is not evidence for an outflow; it is not comparable with the Q11 high-velocity (|v|>350) N limit (<~3%).',
 'see value','km/s, mJy','medium','s75a_pv_spectra.py -> out/q2/s75a.txt/json, s75a_spec.png; s75d_nuclear_3gauss.py -> out/q2/s75d.txt/json')
add('Fluxes, luminosities and recovery of the blue wing (-405..-150 km/s) of the S lobe',
 'S blue lobe, Xb4d@1.05" (Xb4b@1.05" for recovery)',
 'HCN 3-2: 0.518+-0.045 (r=1" aperture), 0.728+-0.036 (r=1.5"), 0.888+-0.092 Jy km/s (2D Gaussian integral); HCO+ 3-2: 0.298+-0.065 (r=1"), 0.444+-0.024 (r=1.5", 3 draws), 0.82+-0.27 Jy km/s (2D Gaussian). Peak (1.05" beam): HCN 0.425+-0.036 (11.7 sigma), HCO+ 0.293+-0.055 Jy/beam km/s (5.3 sigma). Wing/core: HCN 0.64 (r=1"), 0.41 (r=1.5") of the local core flux (-205..95); wing/S-nucleus-core 0.17-0.24. Xb4b@1.05" recovers HCN 0.57+-0.16 (r=1"), 0.52+-0.17 (r=1.5") and HCO+ 1.07+-0.35 / 1.10+-0.29 of the Xb4d wing flux (2D fit integrated: 0.87+-0.46 / 0.75+-0.32 Jy km/s), i.e. consistent with unity within errors; no large resolved-out part is detected but the test is limited (3-4 sigma in Xb4b). HCN/HCO+ (Tb) of the wing: 1.7-1.8+-0.4 (Xb4d, r=1-1.5") but 0.94+-0.35 (Xb4b, r=1"): the array dependence found in Q11 is unchanged (R_wing>R_core robust, >1 not). L\'(3-2) (Solomon 1997, D_L=40 Mpc): HCN 5.3-6.5e5, HCO+ 3.2-5.9e5 K km/s pc^2. Xb4d fluxes are lower limits (wing outside the clean mask).',
 'see value; systematic: clean-mask/residual scale (lower limit), array recovery ~0.5-1','Jy km/s','medium','s75b_wing_fits.py -> out/q2/s75b.txt (AP, FIT lines); s75c_mass_rate.py -> out/q2/s75c.txt (MASK, LUM)')
add('Dense-gas mass and projected mass-outflow rate of the S blue lobe (HCN-based)',
 'S blue lobe (-405..-150 km/s), 1.88" = 365 pc S of S',
 'M_dense = alpha_HCN(1-0)*L\'_HCN(3-2)/r31 = 1.5-1.9e7 Msun for alpha=10 Msun/(K km/s pc^2) and r31=0.35 (range 0.9e7 (r31=0.6) to 2.6e7 (r31=0.25)). Optically thin LTE (Tex 10-50 K) gives N(HCN)=4-9e54 molecules, i.e. 1-2e6 Msun for X(HCN)=1e-8 and 1-2e7 Msun for X=1e-9 (HCO+: 3-6e5 .. 3-7e6 Msun for 1e-8 .. 1e-9), so the two methods agree for X~1e-9; the mass is uncertain by about an order of magnitude (1e6-2e7 Msun). Flux-weighted wing velocity -283 km/s (HCN), -269 (HCO+) relative to systemic; R=365 pc; t=R/v=1.3 Myr. Mdot_dense = M v/R = 12-15 Msun/yr (alpha-based, nominal), 0.8-1.6 Msun/yr (thin LTE X=1e-8), i.e. ~1-15 Msun/yr, x tan(i) for the unknown inclination, and a lower limit to the extent that gas at |v|<150 km/s, flux outside the clean mask and resolved-out flux are not counted. Mdot/SFR(49 Msun/yr, Michiyama+2020) ~0.02-0.3.',
 'factor ~10 (abundance/alpha), x tan i, lower limit','Msun, Msun/yr','low','s75c_mass_rate.py -> out/q2/s75c.txt, s75c.json',
 [A('alpha_HCN(1-0)','10 Msun (K km/s pc^2)^-1 (Gao & Solomon 2004, ApJ 606, 271), applied to HCN(1-0) luminosity = L\'(3-2)/r31'),A('r31','L\'(3-2)/L\'(1-0)=0.35 (0.25-0.6), after the 0.3-0.4 HCN(3-2)/(1-0) of NGC 3256 in Ledger+2021 (2021MNRAS.504.5863L); lobe value not measured here'),A('abundances','X(HCN), X(HCO+) = 1e-9..1e-8 per H2 (assumed), mu=2.72'),A('geometry','projected R and v, time-averaged Mdot=Mv/R, no deprojection')])
add('Red-shifted high-velocity feature 3.4" N of S (between S and N): detection and identity',
 'peak at (E+0.12+-0.08", N+3.40+-0.20") from S (HCN, 180..320 km/s), i.e. 1.8" S of N, on the N-S line',
 'Detected in both lines and both arrays at v=+230..+280 km/s (PV spot, FWHM 140-180 km/s by 2 Gaussians: HCN Xb4d +240+-7 dchi2=275, HCO+ +229+-8 dchi2=138, Xb4b +232+-13/+243+-12): HCN 0.240+-0.028 (8.5 sigma), HCO+ 0.195+-0.033 Jy km/s (5.9 sigma) in r=1" Xb4d@1.05" (2D fit: 0.55+-0.10 and 0.46+-0.12 Jy km/s, peak 7.3/4.3 sigma); Xb4b@1.05": HCN 0.217+-0.049, HCO+ 0.187+-0.035 Jy km/s (recovery 0.9-0.96). HCN/HCO+ (Tb) 1.25+-0.25 (Xb4d), 1.17+-0.3 (Xb4b), about 2x the local core (0.43). Both lines at the same velocity makes a blend unlikely. Offset from the blue lobe: lobe and red feature are collinear with S (PA 183+-1 and 2+-3 deg) and of similar |v| (-250/+250), as expected for a bipolar S outflow, but the N nucleus lies on the same line 1.8" farther N, so a red lobe of the N nucleus, or a high-velocity cloud in the bridge, cannot be excluded; the asymmetry in distance (1.9" vs 3.4") and the fact that the red feature is on the bright bridge also weaken the bipolar reading. Hint level: Xb4d 6-8 sigma but a-posteriori position (no trials calibration done here).',
 'position +-0.2"; fluxes see value','Jy km/s, km/s','low','s75a_pv_spectra.py (Red3.3N rows of out/q2/s75a.txt); s75b_wing_fits.py -> out/q2/s75b.txt (AP/FIT redC)')
r['recipe'].append({'order':len(r['recipe'])+1,'stage':'measurement','description':'Q2: outflow separation: wing moment maps and azimuthal distribution (s74a); PV cuts along PA185 and 1/2-Gaussian decomposition of region spectra (s75a); wing 2D Gaussian fits with injected-noise errors, aperture fluxes, Xb4b recovery, blue-edge velocity, kinematics vs offset (s75b); clean-mask coverage, L\', dense mass and projected Mdot (s75c); 2 narrow+1 broad nuclear decomposition (s75d)',
 'software':'python3 numpy scipy astropy matplotlib; s72_lib loaders','parameters':[A('PV cut','PA=185 deg through S, slit 1" (Xb4d@1.05") / 0.5" (Xb4b@0.5"), 5 strips, 0.25" steps'),A('windows','blue -405..-150, red 180..320 km/s'),A('2D fits','elliptical Gaussian on 5" cut-outs, errors from 15-30 injections into line-free cut-outs')],
 'scripts':['/workspace/scripts/s74a_wing_geometry.py','/workspace/scripts/s75a_pv_spectra.py','/workspace/scripts/s75b_wing_fits.py','/workspace/scripts/s75c_mass_rate.py','/workspace/scripts/s75d_nuclear_3gauss.py','/workspace/scripts/s76_update_report_q2.py']})
if isinstance(r['interpretation'],str):
    r['interpretation']+=("\n\nQ2 (outflow separation): the dense-gas outflow is separable from the nuclei and the disk in these data on one side: a kinematically distinct blue lobe (v=-100..-350 km/s, peak 1.9\" = 365 pc S of S, PA 183 deg, ~400 pc long, ~2-3 beams from the nucleus) in both HCN and HCO+ 3-2, seen in both Xb4d and Xb4b, with HCN/HCO+ ~1-1.8 against 0.37 at S. Dense mass 1e6-2e7 Msun and projected Mdot ~1-15 Msun/yr (lower limits, order-of-magnitude, abundance/alpha dependent); this is ~0.02-0.3 of the SFR. The red side is not mirrored at the same distance; a red feature at +3.4\" N may be the counter-lobe, a N-nucleus outflow, or bridge gas. Not separable: the nuclear wings at S and N (double-peaked nuclear profiles, resolution 0.25-1\" = 50-200 pc) and any CO association (no CO in these data).")
r['caveats'].append("Q2: all Xb4d wing fluxes lie outside the clean mask (residual flux in dirty-beam units), so fluxes, masses and Mdot are lower limits by an unmeasured factor; Xb4b recovers 0.5-1.1 of the Xb4d wing flux within 30-50% errors. Mass depends on alpha(HCN), r31 and X by ~10x; Mdot is projected and neglects tan(i). Gaussian decompositions of double-peaked nuclear profiles are shape dependent. The red feature at +3.4\" N has an a-posteriori position and an ambiguous origin (S counter-lobe vs N nucleus vs bridge cloud). Confirmation needs deeper short-baseline Xb4b/Xb4d imaging of the wing, HCN/HCO+ 1-0 or CO 2-1/3-2 of the lobe for the dense fraction, and a velocity-field model of the S disk.")
json.dump(r,open(R,'w'),indent=1)
